  [4061] = { obj = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards.", money = 16500, rep = { { "Undercity", 250 } } },
  [4062] = { obj = "Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east." },
  [4063] = { obj = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", money = 26500, choose = { { 12109 }, { 12110 }, { 12108 }, { 12111 } } },
  [4081] = { obj = "Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", money = 15500, rep = { { "Orgrimmar", 250 } } },
  [4082] = { obj = "Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", money = 16500, rep = { { "Orgrimmar", 250 } } },
  [4121] = { obj = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort.", money = 26500 },
  [4122] = { obj = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody." },
  [4132] = { obj = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", money = 26500, get = { { 12059 } } },
  [4136] = { obj = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", money = 6000, choose = { { 11865 }, { 11963 }, { 12049 } } },
  [4145] = { obj = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.", money = 7500 },
  [4146] = { obj = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge." },
  [4147] = { obj = "Travel to Marvon Rivetseeker's workshop in Ratchet." },
  [4182] = { obj = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", money = 16500, rep = { { "Darnassus", 250 } } },
  [4183] = { obj = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon.", rep = { { "Darnassus", 150 } } },
  [4184] = { obj = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon. Bolvar resides in Stormwind Keep.", rep = { { "Stormwind", 150 } } },
  [4185] = { obj = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor." },
  [4186] = { obj = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire.", rep = { { "Stormwind", 250 } } },
  [4201] = { obj = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.", money = 8000, choose = { { 11962 }, { 11866 } } },
  [4223] = { obj = "Speak with Marshal Maxwell in the Burning Steppes." },
  [4224] = { obj = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task. You recall Marshal Maxwell telling you to search for him in a cave to the north." },
  [4241] = { obj = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor. You recall Ragged John talking about Windsor being dragged off to a prison.", rep = { { "Stormwind", 250 } } },
  [4242] = { obj = "Give Marshal Maxwell the bad news.", rep = { { "Stormwind", 250 } }, choose = { { 12018 }, { 12021 }, { 12041 } } },
  [4262] = { obj = "Slay Overmaster Pyron and return to Jalinda Sprig. You recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", money = 15500, rep = { { "Gnomeregan Exiles", 250 } } },
  [4263] = { obj = "Find Lord Incendius in Blackrock Depths and destroy him!", money = 8500, rep = { { "Gnomeregan Exiles", 250 } }, choose = { { 12113 }, { 12114 }, { 12112 }, { 12115 } } },
  [4264] = { obj = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", rep = { { "Stormwind", 250 } } },
  [4282] = { obj = "Return Marshal Windsor's Lost Information. Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.", money = 9000, rep = { { "Stormwind", 250 } } },
  [4286] = { obj = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.", money = 8500, rep = { { "Ironforge", 250 } }, get = { { 11883 } } },
  [4322] = { obj = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.", money = 17500, rep = { { "Stormwind", 350 } }, choose = { { 12061 }, { 12062 } }, get = { { 12065 } } },
  [4324] = { obj = "Speak with Yuka Screwspigot in the Burning Steppes." },
  [4341] = { obj = "Travel to Blackrock Depths and find Kharan Mighthammer. The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", rep = { { "Ironforge", 250 } } },
  [4342] = { obj = "Listen as Kharan Mighthammer tells his story." },
  [4361] = { obj = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", rep = { { "Ironforge", 20 } } },
  [4362] = { obj = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", rep = { { "Ironforge", 350 } } },
  [4363] = { obj = "Return to Ironforge and speak with King Magni Bronzebeard.", money = 26500, choose = { { 12548 }, { 12543 } } },
