  [4701] = { obj = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.", money = 18000, rep = { { "Darnassus", 250 } }, choose = { { 15824 }, { 15825 }, { 15827 } } },
  [4724] = { obj = "Slay Halycon, pack mistress of the Bloodaxe worg.", money = 18000, rep = { { "Orgrimmar", 250 } }, choose = { { 15824 }, { 15825 }, { 15827 } } },
  [4726] = { obj = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", money = 7500, rep = { { "Booty Bay", 250 }, { "Everlook", 250 }, { "Gadgetzan", 250 }, { "Ratchet", 250 } } },
  [4734] = { obj = "Use the Eggscilloscope Prototype on an egg in the Rookery.", money = 18000, get = { { 12144 } } },
  [4735] = { obj = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", money = 27000, rep = { { "Booty Bay", 350 }, { "Everlook", 350 }, { "Gadgetzan", 350 }, { "Ratchet", 350 } } },
  [4742] = { obj = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan. The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe." },
  [4743] = { obj = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken. It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!", get = { { 12344 } } },
  [4771] = { obj = "Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink.", money = 27000, rep = { { "Argent Dawn", 500 } }, choose = { { 15853 }, { 15854 } } },
  [4787] = { obj = "Bring the Ancient Egg to Yeh'kinya in Tanaris." },
  [4808] = { obj = "Give Tinkee's Letter to Felnok Steelspring.", rep = { { "Everlook", 75 } } },
  [4809] = { obj = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", rep = { { "Everlook", 250 } } },
  [4810] = { obj = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes.", rep = { { "Steamwheedle Cartel", 75 } }, choose = { { 15862 }, { 15863 } } },
  [4867] = { obj = "Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.", get = { { 15867 } } },
  [4903] = { obj = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", money = 18000, choose = { { 13958 }, { 13959 }, { 13961 }, { 13962 }, { 13963 } } },
  [4907] = { obj = "Speak with Tinkee Steamboil." },
  [4981] = { obj = "Travel to Blackrock Spire and find out what happened to Bijou.", rep = { { "Booty Bay", 250 } } },
  [4982] = { obj = "Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city." },
  [4983] = { obj = "Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath.", money = 18000, rep = { { "Orgrimmar", 250 } }, choose = { { 15858 }, { 15859 } } },
  [5001] = { obj = "Find Bijou's Belongings and return them to her. Good luck!" },
  [5002] = { obj = "Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell.", money = 18000, rep = { { "Stormwind", 250 } } },
  [5066] = { obj = "Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains." },
  [5081] = { obj = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.", money = 18000, choose = { { 13958 }, { 13959 }, { 13961 }, { 13962 }, { 13963 } } },
  [5089] = { obj = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes.", rep = { { "Stormwind", 250 } } },
  [5092] = { obj = "Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill. Return to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", money = 7500, rep = { { "Stormwind", 250 } } },
  [5093] = { obj = "Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity." },
  [5096] = { obj = "Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent. Place the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands.", money = 8000, rep = { { "Undercity", 250 }, { "Thunder Bluff", 75 }, { "Darkspear Trolls", 75 }, { "Orgrimmar", 75 } } },
  [5097] = { obj = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it. Once all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.", money = 8500, rep = { { "Alliance", 250 } } },
  [5098] = { obj = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it. Once all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands.", money = 8500, rep = { { "Horde", 250 } } },
  [5102] = { obj = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done.", money = 27000, rep = { { "Alliance", 500 } }, choose = { { 13966 }, { 13968 }, { 13965 } } },
  [5103] = { obj = "Someone in this world must know what to do with these gauntlets. Good luck!" },
  [5125] = { choose = { { 17044 }, { 17045 } } },
  [5160] = { obj = "Travel to Winterspring and find Haleh. Give her Awbee's scale." },
  [5212] = { obj = "Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", money = 18000, rep = { { "Argent Dawn", 100 } } },
  [5213] = { obj = "Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", rep = { { "Argent Dawn", 250 } }, choose = { { 13209 }, { 19812 } } },
  [5214] = { obj = "Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done.", get = { { 13171 } } },
  [5243] = { obj = "Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", money = 18000, rep = { { "Argent Dawn", 250 } }, choose = { { 13216 }, { 13217 } }, get = { { 3928, 5 }, { 6149, 5 } } },
  [5251] = { obj = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", money = 18000, rep = { { "Argent Dawn", 150 } } },
  [5262] = { obj = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.", rep = { { "Argent Dawn", 150 } } },
  [5263] = { obj = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", rep = { { "Argent Dawn", 150 } } },
  [5281] = { obj = "Find Egan. You only know that he was last seen around Stratholme." },
  [5282] = { obj = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan.", money = 18000, get = { { 13315 } } },
  [5306] = { obj = "Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.", get = { { 12821 } } },
  [5341] = { obj = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.", money = 18000 },
  [5343] = { obj = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.", money = 18000 },
  [5382] = { obj = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete." },
  [5384] = { obj = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.", choose = { { 15805 }, { 15806 } }, get = { { 13544 } } },
  [5461] = { obj = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke." },
  [5462] = { obj = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered." },
  [5463] = { obj = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground." },
  [5464] = { obj = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.", rep = { { "Argent Dawn", 100 } } },
  [5465] = { obj = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake." },
  [5466] = { obj = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", choose = { { 13982 }, { 13986 }, { 13984 } }, get = { { 14002 } } },
  [5505] = { get = { { 13704 } } },
  [5511] = { get = { { 13704 } } },
  [5514] = { obj = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan." },
  [5515] = { obj = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff." },
  [5518] = { obj = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", rep = { { "Booty Bay", 250 }, { "Everlook", 250 }, { "Gadgetzan", 250 }, { "Ratchet", 250 } }, get = { { 18258 } } },
  [5522] = { obj = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.", rep = { { "Argent Dawn", 75 } } },
