  [5528] = { get = { { 18269, 5 }, { 18284, 5 } } },
  [5529] = { obj = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", money = 9000, rep = { { "Argent Dawn", 250 } } },
  [5531] = { obj = "Bring the Frozen Eggs to Betina Bigglezink." },
  [5533] = { obj = "Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands." },
  [5537] = { obj = "Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands." },
  [5538] = { obj = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan." },
  [5542] = { obj = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete." },
  [5722] = { obj = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest." },
  [5723] = { obj = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.", money = 700, rep = { { "Thunder Bluff", 500 } } },
  [5724] = { obj = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.", rep = { { "Thunder Bluff", 500 } }, choose = { { 15452 }, { 15453 } } },
  [5725] = { obj = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.", rep = { { "Undercity", 350 } }, choose = { { 15449 }, { 15450 }, { 15451 } } },
  [5726] = { obj = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.", money = 250, rep = { { "Orgrimmar", 250 } } },
  [5727] = { obj = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.", rep = { { "Orgrimmar", 75 } } },
  [5728] = { obj = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", money = 800, rep = { { "Orgrimmar", 250 } } },
  [5742] = { obj = "Listen to what Tirion Fordring has to say." },
  [5761] = { obj = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", money = 800 },
  [5781] = { obj = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective." },
  [5801] = { obj = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key. Bring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands." },
  [5802] = { obj = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key. Bring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands." },
  [5803] = { obj = "Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands." },
  [5804] = { obj = "Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands." },
  [5845] = { obj = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective." },
  [5846] = { obj = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting." },
  [5848] = { obj = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world. Return the painting to Tirion Fordring." },
  [6133] = { obj = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge. You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", money = 9000 },
  [6135] = { obj = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller. It is said that Duskwing roams the countryside to the north of Marris Stead.", money = 9000, rep = { { "Undercity", 250 } }, choose = { { 16994 }, { 16995 } } },
  [6141] = { obj = "Speak with Brother Anton in Desolace." },
  [6163] = { obj = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.", money = 18000, rep = { { "Undercity", 250 } }, choose = { { 18022 }, { 17001 } } },
  [6403] = { obj = "Follow Reginald Windsor through Stormwind. Protect him from harm!", rep = { { "Alliance", 125 } } },
  [6501] = { obj = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist." },
  [6502] = { obj = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", get = { { 16309 } } },
  [6521] = { obj = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.", money = 2000, choose = { { 17039 }, { 17042 }, { 17043 } } },
  [6522] = { obj = "Take the Small Scroll to Varimathras in the Undercity.", money = 4000 },
  [6561] = { obj = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", money = 6500, rep = { { "Argent Dawn", 200 }, { "Thunder Bluff", 500 } }, choose = { { 7001 }, { 7002 } } },
  [6562] = { obj = "Speak to Je'neu Sancrea in Ashenvale.", rep = { { "Darkspear Trolls", 25 } } },
  [6563] = { obj = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", money = 1400, rep = { { "Darkspear Trolls", 250 } } },
  [6564] = { obj = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.", money = 1100, rep = { { "Darkspear Trolls", 150 } } },
  [6565] = { obj = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", money = 4000, rep = { { "Darkspear Trolls", 350 } }, choose = { { 17694 }, { 17695 } } },
  [6585] = { obj = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife." },
  [6601] = { obj = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." },
  [6602] = { obj = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.", get = { { 16309 } } },
  [6626] = { obj = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", money = 7500 },
  [6627] = { obj = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready." },
  [6821] = { obj = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara." },
  [6921] = { obj = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", money = 4500, rep = { { "Darkspear Trolls", 500 } } },
  [6981] = { obj = "Travel to Ratchet to find someone that can tell you more about the glowing shard. Then, deliver the shard as you are directed." },
  [7028] = { obj = "Collect 15 Theradric Crystal Carvings for Willow in Desolace.", choose = { { 17775 }, { 17776 }, { 17777 }, { 17779 } } },
  [7029] = { obj = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.", choose = { { 17768 }, { 17778 }, { 17770 } } },
  [7041] = { obj = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.", choose = { { 17768 }, { 17778 }, { 17770 } } },
  [7044] = { obj = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond. Find a way to speak with Celebras." },
  [7046] = { obj = "Assist Celebras the Redeemed while he creates the Scepter of Celebras. Speak with him when the ritual is complete.", get = { { 17191 } } },
