  [7066] = { obj = "Seek out Remulos in Moonglade and give him the Seed of Life.", money = 15000, rep = { { "Cenarion Circle", 150 } } },
  [7067] = { obj = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.", money = 14000, get = { { 17774 } } },
  [7068] = { obj = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.", rep = { { "Darkspear Trolls", 350 } }, choose = { { 17772 }, { 17773 } } },
  [7070] = { obj = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.", rep = { { "Stormwind", 350 } }, choose = { { 17772 }, { 17773 } } },
  [7441] = { obj = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", money = 17500, rep = { { "Shen'dralar", 500 } }, choose = { { 18411 }, { 18410 } } },
  [7461] = { obj = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest." },
  [7462] = { obj = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", money = 27000, choose = { { 18420 }, { 18421 }, { 18424 } } },
  [7463] = { obj = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", rep = { { "Shen'dralar", 200 } } },
  [7481] = { obj = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", money = 18000 },
